def catalogs():
    result = {lang: {} for lang in LANGUAGES}
    for row in ROWS.strip().splitlines():
        key, *values = row.split("|")
        for lang, value in zip(LANGUAGES, values, strict=True):
            result[lang][key] = value
    return result
